BEGIN;

-- 1. Deepest children first
DELETE FROM orders.cart_price_change_events;
DELETE FROM orders.order_lines;
DELETE FROM fulfilment.delivery_attempts;
DELETE FROM fulfilment.rider_jobs;
DELETE FROM fulfilment.capacity_slots;
DELETE FROM trust.fraud_signals;

-- 2. Escrow (references orders)
DELETE FROM escrow.ledger_entries;
DELETE FROM escrow.escrow_orders;

-- 3. Stock holds (references catalog.offers, freed after order_lines gone)
DELETE FROM orders.stock_holds;
DELETE FROM orders.checkout_sessions;
DELETE FROM orders.orders;

-- 4. Trust
DELETE FROM trust.seller_risk_tiers;

-- 5. Audit
DELETE FROM audit.outbox_events;

-- 6. Catalog non-seed
DELETE FROM catalog.offer_media
  WHERE offer_id NOT IN (
    '11000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002',
    '11000000-0000-4000-8000-000000000003','11000000-0000-4000-8000-000000000004',
    '11000000-0000-4000-8000-000000000005','11000000-0000-4000-8000-000000000006',
    '11000000-0000-4000-8000-000000000007','11000000-0000-4000-8000-000000000008'
  );

DELETE FROM catalog.offer_price_history
  WHERE offer_id NOT IN (
    '11000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002',
    '11000000-0000-4000-8000-000000000003','11000000-0000-4000-8000-000000000004',
    '11000000-0000-4000-8000-000000000005','11000000-0000-4000-8000-000000000006',
    '11000000-0000-4000-8000-000000000007','11000000-0000-4000-8000-000000000008'
  );

DELETE FROM catalog.offers
  WHERE id NOT IN (
    '11000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000002',
    '11000000-0000-4000-8000-000000000003','11000000-0000-4000-8000-000000000004',
    '11000000-0000-4000-8000-000000000005','11000000-0000-4000-8000-000000000006',
    '11000000-0000-4000-8000-000000000007','11000000-0000-4000-8000-000000000008'
  );

DELETE FROM catalog.lots
  WHERE id NOT IN (
    'f1000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000002',
    'f1000000-0000-4000-8000-000000000003','f1000000-0000-4000-8000-000000000004',
    'f1000000-0000-4000-8000-000000000005','f1000000-0000-4000-8000-000000000006',
    'f1000000-0000-4000-8000-000000000007','f1000000-0000-4000-8000-000000000008'
  );

COMMIT;
